    // A FileSet represents a set of source files.
    // Methods of file sets are synchronized; multiple goroutines
    // may invoke them concurrently.
    //
    // The byte offsets for each file in a file set are mapped into
    // distinct (integer) intervals, one interval [base, base+size]
    // per file. [FileSet.Base] represents the first byte in the file, and size
    // is the corresponding file size. A [Pos] value is a value in such
    // an interval. By determining the interval a [Pos] value belongs
    // to, the file, its file base, and thus the byte offset (position)
    // the [Pos] value is representing can be computed.
    //
    // When adding a new file, a file base must be provided. That can
    // be any integer value that is past the end of any interval of any
    // file already in the file set. For convenience, [FileSet.Base] provides
    // such a value, which is simply the end of the Pos interval of the most
    // recently added file, plus one. Unless there is a need to extend an
    // interval later, using the [FileSet.Base] should be used as argument
    // for [FileSet.AddFile].
    //
    // A [File] may be removed from a FileSet when it is no longer needed.
    // This may reduce memory usage in a long-running application.
    
    template<typename T> requires gocpp::GoStruct<T>
    FileSet::operator T()
    {
        T result;
        result.mutex = this->mutex;
        result.base = this->base;
        result.files = this->files;
        result.last = this->last;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool FileSet::operator==(const T& ref) const
    {
        if (mutex != ref.mutex) return false;
        if (base != ref.base) return false;
        if (files != ref.files) return false;
        if (last != ref.last) return false;
        return true;
    }

